python3 - <<'EOF'
import json

# 1. raw surrogate bytes ED A0 80 inside a JSON string
b = b'{"status":"ok","extra":"\xed\xa0\x80"}'
try:
    r = json.loads(b)
    print("raw surrogate bytes accepted:", repr(r))
except Exception as e:
    print("raw surrogate rejected:", type(e).__name__, e)

# 2. UTF-16 LE with BOM
u16 = '{"status":"ok"}'.encode('utf-16')
try:
    r = json.loads(u16)
    print("utf-16 accepted:", repr(r))
except Exception as e:
    print("utf-16 rejected:", type(e).__name__, e)

# 3. UTF-32 LE with BOM
u32 = '{"status":"ok"}'.encode('utf-32')
try:
    r = json.loads(u32)
    print("utf-32 accepted:", repr(r))
except Exception as e:
    print("utf-32 rejected:", type(e).__name__, e)

# 4. other invalid bytes
for sample in [b'{"a":"\xff"}', b'{"a":"\xc0\x80"}', b'{"a":"\xe4\xb8"}']:
    try:
        print("accepted:", sample, repr(json.loads(sample)))
    except Exception as e:
        print("rejected:", sample, type(e).__name__)

# 5. BOM handling on str input
try:
    print(json.loads('﻿{}'))
except Exception as e:
    print("str BOM:", type(e).__name__, e)
EOF

